package tv.vela.launcher;

import android.app.Activity;
import android.content.*;
import android.content.pm.*;
import android.net.Uri;
import android.os.*;
import android.provider.Settings;
import java.io.*;
import java.lang.ref.WeakReference;
import java.net.*;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.*;
import org.json.*;

/** One bounded job after a visible launch. No alarm, service, polling loop or idle executor. */
final class LiteUpdateManager {
    interface Listener {void changed();}
    interface Transport {InputStream open(String url)throws Exception;}
    private interface Job {void run()throws Exception;}
    private static LiteUpdateManager singleton;
    private final Context context;private final Handler main=new Handler(Looper.getMainLooper());
    private final List<WeakReference<Listener>> listeners=new CopyOnWriteArrayList<>();
    private volatile boolean busy,cancelled;private volatile HttpURLConnection connection;private volatile String status="";private volatile int progress;
    Transport transport=this::open;
    static synchronized LiteUpdateManager get(Context c){if(singleton==null)singleton=new LiteUpdateManager(c);return singleton;}
    private LiteUpdateManager(Context c){context=c.getApplicationContext();cleanup();}
    static SharedPreferences prefs(Context c){return c.getSharedPreferences("lite_updates",0);}
    static File apk(Context c){File dir=new File(c.getFilesDir(),"lite-updates");dir.mkdirs();return new File(dir,"update.apk");}
    private static File partial(Context c){return new File(apk(c).getParentFile(),"download.part");}
    static String version(Context c){try{return c.getPackageManager().getPackageInfo(c.getPackageName(),0).versionName;}catch(Exception missing){return "0.0.0";}}
    static long code(PackageInfo info){return Build.VERSION.SDK_INT>=28?info.getLongVersionCode():info.versionCode;}
    boolean automatic(){return prefs(context).getBoolean("automatic",true);}boolean autoDownload(){return prefs(context).getBoolean("download",true);}
    boolean busy(){return busy;}
    LiteReleaseFeed.Release available(){try{return LiteReleaseFeed.newest(new JSONArray().put(new JSONObject(prefs(context).getString("release","{}"))),version(context),true);}catch(JSONException missing){return null;}}
    boolean ready(){LiteReleaseFeed.Release r=available();return r!=null&&r.tag.equals(prefs(context).getString("downloaded",""))&&apk(context).isFile()&&apk(context).length()==r.size;}
    String status(){if(busy)return status+(progress>0?" · "+progress+"%":"");if(!status.isEmpty())return status;LiteReleaseFeed.Release r=available();return r==null?LiteTvUi.t("Updates are checked on GitHub.","Las actualizaciones se consultan en GitHub."):(ready()?LiteTvUi.t("Ready to install","Lista para instalar"):LiteTvUi.t("Available","Disponible"))+" · "+r.version;}
    void observe(Listener l){forget(l);listeners.add(new WeakReference<>(l));}void forget(Listener l){listeners.removeIf(ref->ref.get()==null||ref.get()==l);}
    private void changed(){main.post(()->{for(WeakReference<Listener> ref:listeners){Listener l=ref.get();if(l!=null)l.changed();else listeners.remove(ref);}});}
    private synchronized void begin(String message,Job job){if(busy)return;busy=true;cancelled=false;progress=0;status=message;changed();ExecutorService executor=Executors.newSingleThreadExecutor();executor.execute(()->{try{job.run();}catch(Exception failed){if(!cancelled)status=LiteTvUi.t("Could not complete the update. Try again.","No se ha podido completar la actualización. Vuelve a intentarlo.");}finally{HttpURLConnection c=connection;if(c!=null)c.disconnect();connection=null;busy=false;executor.shutdown();changed();}});}
    void automaticCheck(){cleanup();if(!automatic())return;long now=System.currentTimeMillis(),checked=prefs(context).getLong("checked",0),attempt=prefs(context).getLong("attempt",0);if((now<checked||now-checked>=86400_000L)&&(now<attempt||now-attempt>=3600_000L))check();else if(autoDownload()&&available()!=null&&!ready()&&now-prefs(context).getLong("downloadAttempt",0)>=3600_000L)download();}
    void check(){begin(LiteTvUi.t("Checking GitHub…","Buscando en GitHub…"),()->{prefs(context).edit().putLong("attempt",System.currentTimeMillis()).apply();byte[] bytes;try(InputStream in=transport.open(LiteReleaseFeed.API);ByteArrayOutputStream out=new ByteArrayOutputStream()){copy(in,out,1024*1024,-1);bytes=out.toByteArray();}LiteReleaseFeed.Release release=LiteReleaseFeed.newest(new JSONArray(new String(bytes,"UTF-8")),version(context),true);SharedPreferences.Editor edit=prefs(context).edit().putLong("checked",System.currentTimeMillis());if(release==null){edit.remove("release").remove("downloaded");apk(context).delete();status=LiteTvUi.t("No newer Lite release has been published.","No hay una versión Lite más reciente publicada.");}else{edit.putString("release",release.json().toString());status=LiteTvUi.t("Available","Disponible")+" · "+release.version;}edit.commit();if(release!=null&&autoDownload()&&!ready())downloadInside(release);});}
    void download(){LiteReleaseFeed.Release r=available();if(r!=null)begin(LiteTvUi.t("Downloading…","Descargando…"),()->downloadInside(r));}
    private void downloadInside(LiteReleaseFeed.Release r)throws Exception{status=LiteTvUi.t("Downloading…","Descargando…");changed();File part=partial(context);prefs(context).edit().putLong("downloadAttempt",System.currentTimeMillis()).remove("downloaded").apply();try{try(InputStream in=transport.open(r.url);FileOutputStream out=new FileOutputStream(part)){copy(in,out,LiteReleaseFeed.MAX_APK,r.size);out.getFD().sync();}verify(context,part,r);checkCancelled();if(apk(context).exists()&&!apk(context).delete())throw new IOException();if(!part.renameTo(apk(context)))throw new IOException();prefs(context).edit().putString("downloaded",r.tag).commit();status=LiteTvUi.t("Update ready to install.","Actualización lista para instalar.");progress=0;}finally{part.delete();}}
    static void verify(Context context,File file,LiteReleaseFeed.Release release)throws Exception{if(file.length()!=release.size)throw new IOException("Size mismatch");MessageDigest digest=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(file)){byte[] b=new byte[8192];for(int n;(n=in.read(b))!=-1;){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException();digest.update(b,0,n);}}StringBuilder hash=new StringBuilder();for(byte b:digest.digest())hash.append(String.format(Locale.ROOT,"%02x",b&255));if(!release.sha256.equals(hash.toString()))throw new IOException("Hash mismatch");PackageManager pm=context.getPackageManager();int flag=Build.VERSION.SDK_INT>=28?PackageManager.GET_SIGNING_CERTIFICATES:PackageManager.GET_SIGNATURES;PackageInfo installed=pm.getPackageInfo(context.getPackageName(),flag),archive=pm.getPackageArchiveInfo(file.getPath(),flag);if(archive==null||!context.getPackageName().equals(archive.packageName)||!release.version.equals(archive.versionName)||code(archive)<=code(installed)||archive.applicationInfo==null||archive.applicationInfo.minSdkVersion>Build.VERSION.SDK_INT)throw new IOException("Wrong application or version");Signature[] before=signatures(pm,installed,null),after=signatures(pm,archive,file.getPath());if(before==null||after==null||before.length==0||!new HashSet<>(Arrays.asList(before)).equals(new HashSet<>(Arrays.asList(after))))throw new IOException("Wrong signer");}
    /** Some Android 9/10 TV firmwares omit SigningInfo for archives. The legacy PM path still verifies the APK; never infer a signer from metadata. */
    private static Signature[] signatures(PackageManager pm,PackageInfo info,String archive)throws Exception{
        if(Build.VERSION.SDK_INT>=28&&info.signingInfo!=null){Signature[] current=info.signingInfo.getApkContentsSigners();if(current!=null&&current.length>0)return current;}
        if(info.signatures!=null&&info.signatures.length>0)return info.signatures;
        PackageInfo legacy=archive==null?pm.getPackageInfo(info.packageName,PackageManager.GET_SIGNATURES):pm.getPackageArchiveInfo(archive,PackageManager.GET_SIGNATURES);
        if(legacy==null||!info.packageName.equals(legacy.packageName)||code(info)!=code(legacy))throw new IOException("Signer metadata unavailable");
        return legacy.signatures;
    }
    void cleanup(){try{long installed=code(context.getPackageManager().getPackageInfo(context.getPackageName(),0));if(prefs(context).getLong("cleaned",-1)==installed)return;File file=apk(context);PackageInfo archive=context.getPackageManager().getPackageArchiveInfo(file.getPath(),0);if(archive==null||code(archive)<=installed){file.delete();partial(context).delete();prefs(context).edit().remove("downloaded").remove("installRequest").remove("installAt").apply();}if(available()==null)prefs(context).edit().remove("release").apply();prefs(context).edit().putLong("cleaned",installed).apply();}catch(Exception ignored){}}
    boolean requested(){if(prefs(context).getString("installRequest","").isEmpty())return false;LiteReleaseFeed.Release r=available();String identity=r==null?"":r.tag+"\n"+r.sha256;long age=System.currentTimeMillis()-prefs(context).getLong("installAt",0);boolean valid=!identity.isEmpty()&&identity.equals(prefs(context).getString("installRequest",""))&&age>=0&&age<3600_000L&&ready();if(!valid)prefs(context).edit().remove("installRequest").remove("installAt").apply();return valid;}
    void requestInstall(Activity activity){LiteReleaseFeed.Release r=available();if(r==null||!ready()||busy)return;prefs(context).edit().putString("installRequest",r.tag+"\n"+r.sha256).putLong("installAt",System.currentTimeMillis()).commit();if(!activity.getPackageManager().canRequestPackageInstalls()){Intent permission=new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+activity.getPackageName()));if(permission.resolveActivity(activity.getPackageManager())==null)permission=new Intent(Settings.ACTION_SECURITY_SETTINGS);try{activity.startActivity(permission);}catch(ActivityNotFoundException|SecurityException unavailable){status=LiteTvUi.t("Open TV settings and allow Vela Lite to install updates.","Abre los ajustes de la TV y permite instalar actualizaciones a Vela Lite.");changed();}}else install(activity);}
    void resumeInstall(LiteHomeActivity activity){if(requested()&&activity.getPackageManager().canRequestPackageInstalls())install(activity);}
    private void install(Activity activity){if(busy||!requested())return;LiteReleaseFeed.Release r=available();WeakReference<Activity> owner=new WeakReference<>(activity);begin(LiteTvUi.t("Verifying update…","Verificando actualización…"),()->{try{verify(context,apk(context),r);checkCancelled();}catch(Exception invalid){prefs(context).edit().remove("installRequest").remove("installAt").remove("downloaded").apply();apk(context).delete();throw invalid;}main.post(()->{if(cancelled)return;Activity target=owner.get();if(target==null||target.isFinishing()||target.isDestroyed()||target instanceof LiteHomeActivity&&!((LiteHomeActivity)target).canShowInstaller()||!requested())return;try{target.startActivityForResult(installIntent(target),902);prefs(context).edit().remove("installRequest").remove("installAt").apply();status=LiteTvUi.t("Confirm the installation on your TV.","Confirma la instalación en la TV.");}catch(ActivityNotFoundException|SecurityException missing){status=LiteTvUi.t("Could not open the installer.","No se ha podido abrir el instalador.");}changed();});});}
    static Intent installIntent(Context c){Uri uri=Uri.parse("content://"+c.getPackageName()+".updates/update.apk");Intent intent=new Intent(Intent.ACTION_VIEW).setDataAndType(uri,"application/vnd.android.package-archive").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION).putExtra(Intent.EXTRA_RETURN_RESULT,true);intent.setClipData(ClipData.newRawUri("Vela Lite update",uri));return intent;}
    void cancel(){cancelled=true;HttpURLConnection c=connection;if(c!=null)c.disconnect();status=LiteTvUi.t("Update cancelled.","Actualización cancelada.");}
    private void checkCancelled()throws InterruptedIOException{if(cancelled||Thread.currentThread().isInterrupted())throw new InterruptedIOException();}
    private void copy(InputStream in,OutputStream out,long limit,long expected)throws Exception{byte[] buffer=new byte[8192];long total=0,start=SystemClock.elapsedRealtime(),notified=0;for(int n;(n=in.read(buffer))!=-1;){checkCancelled();if((total+=n)>limit||expected>0&&total>expected||SystemClock.elapsedRealtime()-start>120000)throw new IOException("Transfer limit");out.write(buffer,0,n);if(expected>0&&SystemClock.elapsedRealtime()-notified>250){progress=(int)(total*100/expected);notified=SystemClock.elapsedRealtime();changed();}}if(expected>0&&total!=expected)throw new IOException("Incomplete download");}
    static boolean allowed(String value){try{URL url=new URL(value);if(!url.getProtocol().equals("https")||url.getUserInfo()!=null||url.getPort()!=-1&&url.getPort()!=443)return false;String host=url.getHost();if(host.equals("api.github.com"))return value.equals(LiteReleaseFeed.API);if(host.equals("github.com"))return url.getPath().startsWith("/LucasLG92/vela-tv/releases/download/lite-v");return host.equals("release-assets.githubusercontent.com")||host.equals("objects.githubusercontent.com")||host.equals("github-releases.githubusercontent.com");}catch(Exception invalid){return false;}}
    private InputStream open(String address)throws Exception{for(int redirects=0;redirects<6;redirects++){checkCancelled();if(!allowed(address))throw new IOException("Untrusted update source");HttpURLConnection c=(HttpURLConnection)new URL(address).openConnection();connection=c;c.setConnectTimeout(8000);c.setReadTimeout(10000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","Vela-Lite-Updater");try{int status=c.getResponseCode();if(status>=300&&status<400){String location=c.getHeaderField("Location");c.disconnect();if(location==null)throw new IOException();address=new URL(new URL(address),location).toString();continue;}if(status!=200)throw new IOException("Release unavailable");return new FilterInputStream(c.getInputStream()){public void close()throws IOException{try{super.close();}finally{c.disconnect();}}};}catch(Exception failed){c.disconnect();throw failed;}}throw new IOException("Redirect limit");}
}
